 extra+='mov w24,w25\n'+number(b)+f'mov w9,#{TEXT[10]-BOX}\nadd x10,x28,x9\nldr w11,[x22,#16]\nmov w9,#16\ncmp w11,w9\ncsel w11,w11,w9,lo\nmov w12,#0\nmedal_copy1110:\ncmp w12,w11\nb.hs medal_end1110\nadd x9,x22,#20\nldrh w13,[x9,w12,uxtw #1]\nstrh w13,[x10,w12,uxtw #1]\nadd w12,w12,#1\nb medal_copy1110\nmedal_end1110:\nstrh wzr,[x10,w12,uxtw #1]\n'
