 s=f'bl {sync:#x}\n'+b.ctx('life_rework')+b.text('ServiceReport1110','No posting order is due. Your current base and coworkers remain in place.')+b.get('BaseDue1110')+'cmp w24,#1\nb.ne finish\n'+h.load_occupation()+'\nldr w9,[x8,#0x10]\ncmp w9,#3\nb.ne finish\nmov x19,x8\n'+getstr('BaseTarget1110')+'cbz x0,finish\nmov x8,x0\n'+h.compare_key('Home','transfer_home1110','transfer_overseas1110')+'\ntransfer_overseas1110:\n'+getstr('ServiceHome1110')+'cbz x0,finish\nmov x8,x0\n'+h.compare_key('United States','transfer_us1110','transfer_us_alias1110')+'\ntransfer_us_alias1110:\n'+h.compare_key('United States of America','transfer_us1110','finish')+'\ntransfer_us1110:\n'+getstr('BaseTarget1110')+'mov x27,x0\nmov x8,x0\n'
