 transfer=b.routine('connected_transfer_actual_military_posting',s)
 s='mov w19,w0\n'+f'bl {sync:#x}\n'+b.ctx('life_rework')+'cmp w19,#621\nb.eq service_discharge1110\ncmp w19,#622\nb.eq service_transfer1110\ncmp w19,#623\nb.eq service_transfer1110\ncmp w19,#624\nb.eq service_stay1110\nb finish\nservice_transfer1110:\n'+f'bl {transfer:#x}\nb finish\nservice_stay1110:\n'+b.get('BaseDue1110')+'cbz w24,service_no_due1110\n'+b.get('Year','w25')+b.rng(3)+'add w24,w24,#2\nadd w24,w24,w25\n'+b.put('BaseDueYear1110')+b.set('BaseDue1110',0)+b.text('ServiceReport1110','Your request to stay is accepted. You keep your current base and coworkers; the next posting review is in two to four years.')+b.string('My unit accepted my request to stay at the current base.')+f'bl {b.journal55:#x}\nb finish\nservice_no_due1110:\n'+b.text('ServiceReport1110','No posting review is due. Check your next review year before requesting a change.')+'b finish\nservice_discharge1110:\n'+b.text('ServiceReport1110','An early release is unavailable here. Complete at least four service years and wait until the world-war campaign has ended. Ordinary military retirement and discharge rules remain available.')+b.get('War')+'cbnz w24,finish\n'+b.get('ServiceYears1110')+'cmp w24,#4\nb.lt finish\n'+h.load_occupation()+'\nldr w9,[x8,#0x10]\ncmp w9,#3\nb.ne finish\n'+h.load_game()+'\nldr x0,[x8,#0x28]\nmov w1,#1\nmov x2,xzr\nbl 0x2a7dea8\n'+b.ctx('life_rework')+b.text('ServiceReport1110','Your honorable discharge is recorded. You leave active service and return to civilian life. Check your education benefit before applying to college.')+'b finish'
