 eligible=b.ctx('life_rework')+b.get('GIEligible1110')+'cmp w24,#1\nb.ne finish\n'+b.get('GIUsed1110')+'cbnz w24,finish\n'+b.get('Year')+'cmp w24,#1944\nb.lt finish\nldr x8,[x19,#0x170]\ncbz x8,finish\nldr w9,[x8,#0x10]\ncmp w9,#11\nb.eq gi_type_ok1110\ncmp w9,#12\nb.ne finish\ngi_type_ok1110:\nldr w9,[x8,#0x20]\ncmp w9,#1\nb.lt finish\ncmp w9,#4\nb.gt finish\n'
 s='mov x26,x20\ncbz x19,finish\ncbz x26,finish\n'+eligible+'ldr w9,[x26,#0x18]\ncbz w9,finish\ncmp w9,#16\nb.hi finish\nmov w25,w9\nldr x8,[x26,#0x10]\ncbz x8,finish\nldr x8,[x8,#0x20]\ncbz x8,finish\nldr x0,[x8]\nbl 0x2237158\ncbz x0,finish\nmov x27,x0\n'+b.string('Use the GI Bill')+'mov x1,x0\nmov x0,x27\nmov w2,#0\nmov w3,#1\nmov x4,xzr\nbl 0x2a1bcf0\nldr x8,[x26]\nmov x0,x26\nmov x1,x27\nldr x9,[x8,#0x308]\nldr x2,[x8,#0x310]\nblr x9\n'+f'adr x28,{gi:#x}\nldr x0,[x28]\ncbz w0,gi_no_old_root1110\nbl 0x223e784\ngi_no_old_root1110:\nmov x0,x19\nmov w1,#0\nbl 0x223e704\nstr x0,[x28]\nstr w25,[x28,#8]\nstr wzr,[x28,#24]\nbl {owner:#x}\nstr x0,[x28,#16]\nb finish'
