 b.install('connected_select_original_gi_funding',0x25bd654,s,custom_resume=0x25be698)
 s=f'adr x28,{gi:#x}\nldr w9,[x28,#24]\ncbz w9,finish\nldr x0,[x28]\nbl 0x223e73c\ncmp x0,x19\nb.ne finish\nbl {owner:#x}\nldr x9,[x28,#16]\ncmp x0,x9\nb.ne finish\n'+h.load_occupation()+'\ncmp x8,x20\nb.ne finish\nldr w9,[x8,#0x10]\ncmp w9,#1\nb.ne finish\nmov x0,x20\nfmov s0,wzr\nmov x1,xzr\nbl 0x2b6de9c\nstr wzr,[x28,#24]\n'+b.ctx('life_rework')+b.set('GIUsed1110',1)+'ldr x8,[x19,#0x170]\nldr w24,[x8,#0x20]\n'+b.put('GICollegeYears1110')+b.text('GIReport1110','Your GI Bill benefit is paying tuition for this course. You did not take out a student loan or make a scholarship attempt. The single-course benefit is now in use.')+b.string('I used my GI Bill benefit to fund college without a student loan.')+f'bl {b.journal55:#x}\nb finish'
