  gate+=h.compare_key(country,'enlist_country1110_'+str(n),'enlist_country_next1110_'+str(n))+f'\nenlist_country1110_{n}:\ncmp w25,#{first}\nb.lt military_rejected1108\ncmp w25,#1918\nb.lt enlist_ok1108\ncmp w25,#{1940 if country=="United States"else second}\nb.lt military_rejected1108\ncmp w25,#1945\nb.lt enlist_ok1108\nb military_rejected1108\nenlist_country_next1110_{n}:\n'
