def _personnel(b):
 # x0=script, x1=person, w2=minimum rank. Person Age is an audited int field.
 s='cbz x0,finish\ncbz x1,finish\nmov x19,x0\nmov x20,x1\nmov w27,w2\nmov x1,xzr\nbl 0x2c4a6b4\ncmp w0,#3\nb.ne finish\nmov x0,x19\nmov x1,xzr\nbl 0x2c4a7c4\nmov w21,w0\ncmp w21,#1\nb.eq rank_status_ok1110\ncmp w21,#2\nb.ne finish\nrank_status_ok1110:\nldr w22,[x20,#0x20]\nmov w9,#18\ncmp w21,#2\nmov w10,#22\ncsel w23,w10,w9,eq\ncmp w22,w23\ncsel w22,w22,w23,ge\nmov x0,x20\nmov x1,xzr\nbl 0x2c44914\nmov w25,#0\ncbz x0,rank_name_ready1110\nldr w25,[x0,#16]\nrank_name_ready1110:\nand w25,w25,#3\nadd w24,w23,w25\nsub w26,w22,w24\ncmp w26,#0\ncsel w26,w26,wzr,ge\nmov w9,#4\nudiv w26,w26,w9\nadd w26,w26,#1\nmov w9,#8\ncmp w26,w9\ncsel w26,w26,w9,le\ncmp w26,w27\ncsel w26,w26,w27,ge\nmov w0,w26\nmov w1,w21\nmov x2,xzr\nbl 0x27fe124\ncbz x0,finish\nsub w9,w26,#1\nmov w10,#3\nmadd w9,w9,w10,w23\ncmp w22,w9\ncsel w22,w22,w9,ge\nmov x0,x20\nmov w1,w22\nmov x2,xzr\nbl 0x2c420f4\nmov x0,x19\nmov w1,w26\nmov x2,xzr\nbl 0x2c4a7dc\nmov x0,x19\nmov w1,w24\nmov x2,xzr\nbl 0x2c4a7ec\nmov x0,x19\nsub w1,w26,#1\nmov x2,xzr\nbl 0x2c4a7fc\nmov x0,x19\nmov x1,xzr\nmov x2,xzr\nbl 0x2c4a968\nb finish'
 normal=b.routine('connected_normalize_native_military_coworker',s)
